{
    "data convert": [
        {
            "type": "raw",
            "field name": "Gene",
            "raw field": "Gene"
        },
        {
            "type": "raw",
            "field name": "Lung TWAS",
            "raw field": "Lung_TWAS"
        },
        {
            "type": "raw",
            "field name": "Blood eGene",
            "raw field": "Blood_eGene"
        },
        {
            "type": "raw",
            "field name": "Hi-C",
            "raw field": "Hi-C"
        },
        {
            "type": "raw",
            "field name": "Open Targets asthma score",
            "raw field": "Asthma_score"
        },
        {
            "type": "raw",
            "field name": "Drug-gene Interaction DB",
            "raw field": "DGIdb"
        },
        {
            "type": "raw",
            "field name": "Druggable genome",
            "raw field": "Druggable_genome"
        },
        {
            "type": "raw",
            "field name": "Asthma drug target",
            "raw field": "Asthma_drug_target"
        }],
    "tool tips": {
        "Gene": "Prioritized gene, linked to its Gene page in the Lung Disease Knowledge Portal",
        "Lung TWAS" : "Whether the gene has transcriptome-wide significance (p < 2.51E−6) in a lung TWAS analysis",
        "Blood eGene" : "Whether the gene is an eGene for a blood eQTL that colocalizes (H4 > 60%) with an asthma-associated SNP",
        "Hi-C" : "Whether the gene is in contact with an asthma-associated SNP",
        "Open Targets asthma score" : "Overall asthma association score for the gene from the Open Targets platform",
        "Drug-gene Interaction DB" : "Whether the gene is categorized as druggable in DGIdb",
        "Druggable genome" : "Whether the gene is categorized as druggable in the druggable genome study (Finan et al. 2017)",
        "Asthma drug target" : "Whether the gene is present on a recent list of asthma drug targets (El-Husseini et al. 2020)"
    },
    "column formatting": {
        "Gene": {
            "type": ["link"],
            "link to": "https://lung.hugeamp.org/gene.html?gene=",
            "new tab": "true"

        }
    },
    "top rows": [
        "Gene",
        "Lung TWAS",
        "Blood eGene",
        "Hi-C",
        "Open Targets asthma score",
        "Drug-gene Interaction DB",
        "Druggable genome",
        "Asthma drug target"
    ]
}

